      }
      is IconTreatment -> {
        stream.write(130)
        writeValue(stream, value.raw.toLong())
      }
      is AppEntry -> {
        stream.write(131)
        writeValue(stream, value.toList())
      }
      is AppChangeEvent -> {
        stream.write(132)
        writeValue(stream, value.toList())
      }
      is IconStyle -> {
